const BY_NAME = new Map(POINT_SYMBOLS.map((s) => [s.name, s]))

/** The symbol for a stored `pointIcon`, or undefined if the name is unknown — a renderer
 *  saved against an icon later removed from the set must degrade to a circle, not throw. */
export function pointSymbol(name: string | null | undefined): PointSymbol | undefined {
  return name ? BY_NAME.get(name) : undefined
}
